import {
  BoxGeometry,
  CylinderGeometry,
  Group,
  Mesh,
  MeshStandardMaterial,
  SphereGeometry,
} from 'three';

class BoxLamp extends Mesh {}
class SphereLamp extends Mesh {}

function material(color) {
  return new MeshStandardMaterial({ color });
}

/**
 * Base fixture: a market stall.
 */
export function buildMarketStall() {
  const stall = new Group();
  stall.name = 'market-stall';

  const counter = new Mesh(new BoxGeometry(3, 1, 1), material(0x8b5a2b));
  counter.name = 'counter';
  counter.position.set(0, 0.5, 0);
  stall.add(counter);

  const awning = new Mesh(new BoxGeometry(3.4, 0.1, 1.6), material(0xcc2222));
  awning.name = 'awning';
  awning.position.set(0, 2.2, -0.2);
  stall.add(awning);

  const crates = new Group();
  crates.name = 'crates';
  for (let i = 0; i < 3; i++) {
    const crate = new Mesh(new BoxGeometry(0.5, 0.5, 0.5), material(0xc68e3d));
    crate.name = `crate-${i + 1}`;
    crate.position.set(-1 + i * 1, 1.25, 0);
    crates.add(crate);
  }
  stall.add(crates);

  const barrel = new Mesh(new CylinderGeometry(0.35, 0.35, 0.9, 16), material(0x6b4423));
  barrel.name = 'barrel';
  barrel.position.set(1.8, 0.45, 0);
  stall.add(barrel);

  const lamp = new BoxLamp(new BoxGeometry(0.25, 0.25, 0.25), material(0xffee88));
  lamp.name = 'lamp';
  lamp.position.set(-1.5, 2.8, -0.2);
  stall.add(lamp);

  return stall;
}

/**
 * Variant fixture relative to the base market stall:
 *  - one crate deleted (crate-3)
 *  - an extra barrel added (barrel-extra)
 *  - the awning moved 0.5 in x
 *  - the box lamp swapped for a sphere lamp (different class)
 */
export function buildMarketStallVariant() {
  const stall = new Group();
  stall.name = 'market-stall';

  const counter = new Mesh(new BoxGeometry(3, 1, 1), material(0x8b5a2b));
  counter.name = 'counter';
  counter.position.set(0, 0.5, 0);
  stall.add(counter);

  const awning = new Mesh(new BoxGeometry(3.4, 0.1, 1.6), material(0xcc2222));
  awning.name = 'awning';
  awning.position.set(0.5, 2.2, -0.2); // moved 0.5 in x
  stall.add(awning);

  const crates = new Group();
  crates.name = 'crates';
  for (let i = 0; i < 2; i++) {
    const crate = new Mesh(new BoxGeometry(0.5, 0.5, 0.5), material(0xc68e3d));
    crate.name = `crate-${i + 1}`;
    crate.position.set(-1 + i * 1, 1.25, 0);
    crates.add(crate);
  }
  stall.add(crates); // crate-3 deleted

  const barrel = new Mesh(new CylinderGeometry(0.35, 0.35, 0.9, 16), material(0x6b4423));
  barrel.name = 'barrel';
  barrel.position.set(1.8, 0.45, 0);
  stall.add(barrel);

  const barrelExtra = new Mesh(new CylinderGeometry(0.35, 0.35, 0.9, 16), material(0x6b4423));
  barrelExtra.name = 'barrel-extra'; // added
  barrelExtra.position.set(2.5, 0.45, 0);
  stall.add(barrelExtra);

  const lamp = new SphereLamp(new SphereGeometry(0.18, 16, 12), material(0xffee88));
  lamp.name = 'lamp'; // retyped: BoxLamp -> SphereLamp
  lamp.position.set(-1.5, 2.8, -0.2);
  stall.add(lamp);

  return stall;
}

