/**
 * Scene-graph diff tool.
 *
 * Walks two scene trees by path (names joined with "/", falling back to the
 * child index when a node has no name) and reports added, removed, moved and
 * retyped nodes.
 */

const EPSILON = 1e-9;

function childKey(child, index) {
  return child.name ? child.name : String(index);
}

function flatten(root) {
  const nodes = new Map();

  const visit = (node, path) => {
    const entry = {
      type: node.constructor.name,
      position: node.position
        ? [node.position.x, node.position.y, node.position.z]
        : [0, 0, 0],
    };
    nodes.set(path, entry);

    const children = Array.from(node.children || []);
    children.forEach((child, index) => {
      visit(child, path ? `${path}/${childKey(child, index)}` : childKey(child, index));
    });
  };

  visit(root, root.name ? root.name : '');

  return nodes;
}

function hasMoved(a, b) {
  return (
    Math.abs(a[0] - b[0]) > EPSILON ||
    Math.abs(a[1] - b[1]) > EPSILON ||
    Math.abs(a[2] - b[2]) > EPSILON
  );
}

const byPath = (x, y) => (x.path < y.path ? -1 : x.path > y.path ? 1 : 0);

/**
 * Diff two scene graphs.
 *
 * @param {import('three').Object3D} a - base scene
 * @param {import('three').Object3D} b - variant scene
 * @returns {{added: string[], removed: string[], moved: {path: string, from: number[], to: number[]}[], retyped: string[]}}
 */
export function diffScenes(a, b) {
  const mapA = flatten(a);
  const mapB = flatten(b);

  const added = [];
  const removed = [];
  const moved = [];
  const retyped = [];

  for (const [path, entryA] of mapA) {
    const entryB = mapB.get(path);
    if (!entryB) {
      removed.push(path);
      continue;
    }
    if (entryA.type !== entryB.type) {
      retyped.push(path);
    }
    if (hasMoved(entryA.position, entryB.position)) {
      moved.push({ path, from: entryA.position.slice(), to: entryB.position.slice() });
    }
  }

  for (const path of mapB.keys()) {
    if (!mapA.has(path)) {
      added.push(path);
    }
  }

  // Deterministic output regardless of child ordering in either tree.
  added.sort();
  removed.sort();
  retyped.sort();
  moved.sort(byPath);

  return { added, removed, moved, retyped };
}

