import { describe, expect, it } from 'vitest';
import { Group, Mesh, BoxGeometry, MeshStandardMaterial } from 'three';
import { diffScenes } from '../src/diff.js';
import { buildMarketStall, buildMarketStallVariant } from './fixtures.js';

function cloneDeep(root) {
  const copy = root.clone(true);
  // three's Object3D.clone does not deep-clone geometry/material references,
  // but for diffing purposes only the graph shape, class names and transforms
  // matter, so this is sufficient.
  return copy;
}

describe('diffScenes', () => {
  it('reports exactly the four changes between the stall and its variant', () => {
    const diff = diffScenes(buildMarketStall(), buildMarketStallVariant());

    expect(diff.added).toEqual(['market-stall/barrel-extra']);
    expect(diff.removed).toEqual(['market-stall/crates/crate-3']);
    expect(diff.retyped).toEqual(['market-stall/lamp']);

    expect(diff.moved).toHaveLength(1);
    expect(diff.moved[0].path).toBe('market-stall/awning');
    expect(diff.moved[0].from).toEqual([0, 2.2, -0.2]);
    expect(diff.moved[0].to).toEqual([0.5, 2.2, -0.2]);
  });

  it('yields four empty arrays when diffing a scene against a deep clone', () => {
    const scene = buildMarketStall();
    const diff = diffScenes(scene, cloneDeep(scene));

    expect(diff.added).toEqual([]);
    expect(diff.removed).toEqual([]);
    expect(diff.moved).toEqual([]);
    expect(diff.retyped).toEqual([]);
  });

  it('is stable across two runs', () => {
    const a = buildMarketStall();
    const b = buildMarketStallVariant();

    const first = JSON.stringify(diffScenes(a, b));
    const second = JSON.stringify(diffScenes(a, b));

    expect(second).toBe(first);
  });

  it('does not produce false positives when child order differs but names exist', () => {
    const makeScene = (order) => {
      const root = new Group();
      root.name = 'scene';

      const meshes = ['alpha', 'beta', 'gamma'].map((name) => {
        const mesh = new Mesh(new BoxGeometry(1, 1, 1), new MeshStandardMaterial());
        mesh.name = name;
        return mesh;
      });

      order.forEach((index) => root.add(meshes[index]));
      return root;
    };

    // Same nodes, same transforms, different insertion order.
    const diff = diffScenes(makeScene([0, 1, 2]), makeScene([2, 0, 1]));

    expect(diff.added).toEqual([]);
    expect(diff.removed).toEqual([]);
    expect(diff.moved).toEqual([]);
    expect(diff.retyped).toEqual([]);
  });
});

